\label{l:ai}
Suppose that $q=2$ and $d\ge 2$, and let $\Lambda$ be an almost independent subset of $V$ of cardinality at least $d+1$. Then $\Lambda$ is $\mathrm{AGL}_d(2)$-conjugate to one of the following:
\begin{enumerate}
\item\label{l:ai1}$
\{0,e_1,\ldots,e_d\}$,
in which case $\Lambda$ is independent;

\item\label{l:ai2}
$\left\{0,e_1,\ldots,e_{d-1},
\sum_{i=1}^{d-1}e_i\right\}$,
where $d$ is odd;

\item\label{l:ai3}
$
\left\{0,e_1,\ldots,e_d,
\sum_{i=1}^d e_i\right\}$,
where $d$ is even.
\end{enumerate}

\label{l:binarysubgroups}
Let $K\le \mathrm{AGL}_d(2)$. Then
$\mathrm{RC}(K)\le d+1$.

\label{l:B0def}
    Take $\alpha, \beta,c_0,v_0$ and $B_0$ as defined above. Then \begin{equation*}\label{eq:B0}
B_0=I_d+c_0\delta
\quad\text{and}\quad
v_0=\frac{1}{1-\alpha}\delta.
\end{equation*}

\label{eq:normalizer}
    Fix the notation of above. Then \begin{equation*}
{\bf N}_{\mathrm{PGL}_2(q)}(\overline{N})=\overline{N}.\end{equation*}

\label{thrm:calculations}
    Let $G=V\rtimes G_0$ where $V$ is a vector space of dimension $d\geq 2$ over $\mathbb{F}_2$ and $G_0$ is an irreducible subgroup of $\mathrm{SL}_d(2)$. If $G_0$ is one of
    \begin{enumerate}
        \item $\mathrm{SL}_d(2)$, $d$ odd;
        \item $\Omega^\pm_d(2)$, $d\geq 6$ even; or
        \item $\mathrm{Alt}(m)$, $m\in\{d+1,d+2\}$, $d$ even, acting on the fully deleted permutation module,
    \end{enumerate}
    then $\mathrm{RC}(G)=d+1$.
    If $G_0$ is one of
    
    \begin{enumerate}
        \item[(4)] $\mathrm{Sp}_d(2)$, $d\geq 4$;
        \item[(5)] $\mathrm{O}^\pm_d(2)$, $d\geq 4$; or
        \item[(6)] $\mathrm{Sym}(m)$, $m\in\{d+1,d+2\}$, $d$ even, acting on the fully deleted permutation module,
    \end{enumerate}
    then $\mathrm{RC}(G)\ne d+1$.

\label{l:symmetric-pairing-complete}
For all $i,j\in\mathcal I$, we have $v_ic_j=v_jc_i$.
Moreover, every $B_i$ has order $2$ or $3$.
